Dataspatium.assets.register("presets/api/kuntien-avainluvut.api.json","text","{\n  \"format\": \"dataspatium-api/1\",\n  \"id\": \"kuntien-avainluvut\",\n  \"name\": \"Kommunernas nyckeltal (Statistikcentralen)\",\n  \"publisher\": \"Statistikcentralen (Tilastokeskus)\",\n  \"description\": \"Nyckeltal för Finlands kommuner, välfärdsområden och landskap efter områdesindelningens år: befolkning, boende, utbildning, arbetsmarknad, näringsliv och kommunal ekonomi. Bläddra, välj tabell och värden per variabel.\",\n  \"docs\": \"https://stat.fi/fi/palvelut/tilastodatapalvelut/avoin-data-ja-rajapinnat/tietokantojen-rajapintakaytto\",\n  \"license\": { \"name\": \"CC BY 4.0\", \"url\": \"https://creativecommons.org/licenses/by/4.0/\" },\n  \"level\": 1,\n  \"country\": \"FI\",\n  \"baseUrl\": \"https://pxdata.stat.fi/PxWeb/api/v1/sv/Kuntien_avainluvut\",\n  \"auth\": { \"type\": \"none\" },\n  \"rateLimit\": { \"requests\": 30, \"perSeconds\": 10 },\n  \"family\": { \"type\": \"pxweb\", \"version\": 1, \"maxCells\": 100000, \"urls\": { \"fi\": \"https://pxdata.stat.fi/PxWeb/api/v1/fi/Kuntien_avainluvut\", \"sv\": \"https://pxdata.stat.fi/PxWeb/api/v1/sv/Kuntien_avainluvut\", \"en\": \"https://pxdata.stat.fi/PxWeb/api/v1/en/Kuntien_avainluvut\" } },\n  \"notes\": \"Ange källa: Statistikcentralen.\",\n  \"i18n\": {\n    \"en\": { \"name\": \"Municipal key figures (Statistics Finland)\", \"publisher\": \"Statistics Finland (Tilastokeskus)\", \"description\": \"Key figures for Finland's municipalities, wellbeing services counties and regions by the year of the regional division: population, housing, education, labour market, business and municipal finances. Browse, pick a table and values per variable.\", \"notes\": \"Cite the source: Statistics Finland.\" },\n    \"da\": { \"name\": \"Kommunernes nøgletal (Statistikcentralen)\", \"publisher\": \"Statistikcentralen (Tilastokeskus)\", \"description\": \"Nøgletal for Finlands kommuner, velfærdsområder og landskaber efter områdeinddelingens år: befolkning, boliger, uddannelse, arbejdsmarked, erhverv og kommunal økonomi. Gennemse, vælg tabel og værdier pr. variabel.\", \"notes\": \"Angiv kilde: Statistikcentralen.\" },\n    \"nb\": { \"name\": \"Kommunenes nøkkeltall (Statistikcentralen)\", \"publisher\": \"Statistikcentralen (Tilastokeskus)\", \"description\": \"Nøkkeltall for Finlands kommuner, velferdsområder og landskap etter områdeinndelingens år: befolkning, bolig, utdanning, arbeidsmarked, næringsliv og kommunal økonomi. Bla, velg tabell og verdier per variabel.\", \"notes\": \"Oppgi kilde: Statistikcentralen.\" },\n    \"fi\": { \"name\": \"Kuntien avainluvut (Tilastokeskus)\", \"publisher\": \"Tilastokeskus\", \"description\": \"Suomen kuntien, hyvinvointialueiden ja maakuntien avainluvut aluejaon vuoden mukaan: väestö, asuminen, koulutus, työmarkkinat, elinkeinot ja kuntatalous. Selaa, valitse taulukko ja arvot muuttujittain.\", \"notes\": \"Mainitse lähde: Tilastokeskus.\" },\n    \"is\": { \"name\": \"Lykiltölur sveitarfélaga (Hagstofa Finnlands)\", \"publisher\": \"Tilastokeskus (Hagstofa Finnlands)\", \"description\": \"Lykiltölur fyrir sveitarfélög, velferðarsvæði og landshluta Finnlands eftir ári svæðaskiptingar: mannfjöldi, húsnæði, menntun, vinnumarkaður, atvinnulíf og fjármál sveitarfélaga. Flettu, veldu töflu og gildi fyrir hverja breytu.\", \"notes\": \"Tilgreindu heimild: Tilastokeskus.\" }\n  }\n}\n");
